<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import type {ExperimentTracker} from './experimentTracker'
import {experimentPageLabel} from './experimentRuntime'
import {useDialogAccess} from './dialogAccess'
import {useOverlayHost} from './overlayHost'
const props=defineProps<{open:boolean;tracker:ExperimentTracker;projectId?:string}>()
const emit=defineEmits<{close:[]}>(),host=useOverlayHost(),dialog=ref<HTMLElement>()
const keyboard=useDialogAccess(()=>props.open,dialog)
const notes=ref<any[]>([]),loading=ref(false),error=ref(''),scope=ref(props.projectId?'current':'all'),query=ref(''),selected=ref('')
const categories:Record<string,string>={think_aloud:'思考／文字反馈',bug:'问题或 Bug',discomfort:'不舒服／困惑',idea:'改进想法'}
const visible=computed(()=>notes.value.filter(note=>[note.text,experimentPageLabel(note.page),categories[note.category]||note.category].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())))
const detail=computed(()=>notes.value.find(note=>note.id===selected.value))
let requestSequence=0
async function load(){
 const sequence=++requestSequence;loading.value=true;error.value='';notes.value=[];selected.value=''
 try{
  const project=scope.value==='current'&&props.projectId?'?projectId='+encodeURIComponent(props.projectId):''
  const rows=await props.tracker.request('/experiment-notes'+project)
  if(sequence===requestSequence&&props.open)notes.value=rows
 }catch(e:any){if(sequence===requestSequence)error.value=e.message||'便笺记录暂时无法读取，请重试。'}
 finally{if(sequence===requestSequence)loading.value=false}
}
watch([()=>props.open,()=>props.projectId,scope],([open])=>{if(open)void load();else requestSequence++})
</script>
<template><Teleport :to="host"><div v-if="open" class="note-history-backdrop" data-experiment-ignore data-screenshot-ignore @click.self="emit('close')"><section ref="dialog" class="note-history" role="dialog" aria-modal="true" aria-labelledby="note-history-title" tabindex="-1" @keydown="keyboard" @keydown.esc.stop.prevent="emit('close')">
 <header><div><small>SCREENSHOT NOTES</small><h2 id="note-history-title">截图与便笺记录</h2><p>截图和文字保存在本机；实验内外的便笺都可以在这里查看。</p></div><button class="icon-button" aria-label="关闭便笺记录" @click="emit('close')">×</button></header>
 <div class="note-history-tools"><label><span class="sr-only">便笺项目范围</span><select v-model="scope" aria-label="便笺项目范围"><option v-if="projectId" value="current">当前项目</option><option value="all">全部项目</option></select></label><input v-model="query" type="search" aria-label="搜索便笺记录" placeholder="搜索便笺文字、模块或类型…"><button :disabled="loading" @click="load">刷新</button></div>
 <div class="note-history-body" :aria-busy="loading">
  <p v-if="loading" role="status">正在读取便笺记录…</p><div v-else-if="error" role="alert" class="note-history-error"><p>{{error}}</p><button @click="load">重新读取</button></div>
  <template v-else-if="detail"><button class="note-history-back" @click="selected=''">← 返回记录列表</button><div class="note-detail"><a v-if="detail.imageUrl" :href="detail.imageUrl" target="_blank" rel="noopener"><img :src="detail.imageUrl" alt="便笺截图原图"><span>在新窗口查看原图 ↗</span></a><small>{{new Date(detail.createdAt).toLocaleString()}} · {{experimentPageLabel(detail.page)}} · {{categories[detail.category]||'便笺'}}</small><p>{{detail.text||'此便笺仅包含截图。'}}</p><small>{{detail.runId?'已关联实验记录':'独立便笺'}}</small></div></template>
  <template v-else><div class="note-history-summary">{{visible.length}} 条记录 <span v-if="query.trim()">· 已按搜索条件筛选</span></div><div v-if="!visible.length" class="note-history-empty"><span>笺</span><h3>{{query.trim()?'没有找到匹配的便笺':'这里还没有便笺记录'}}</h3><p>{{query.trim()?'换一个关键词试试。':scope==='current'?'可以切换到「全部项目」查看其他记录，或关闭后新增便笺。':'点击「截图便笺」或「文字便笺」，保存后即可在这里查看。'}}</p></div><div v-else class="note-history-grid"><button v-for="note in visible" :key="note.id" class="note-history-card" @click="selected=note.id"><div class="note-history-image"><img v-if="note.imageUrl" :src="note.imageUrl" alt="已保存的便笺截图" loading="lazy"><span v-else>文字便笺</span></div><div class="note-history-caption"><span class="note-category">{{categories[note.category]||'便笺'}}</span><p>{{note.text||'仅截图，未填写文字'}}</p><small>{{experimentPageLabel(note.page)}} · {{new Date(note.createdAt).toLocaleString()}}</small><footer><span>{{note.runId?'实验内便笺':'独立便笺'}}</span><span>查看详情 ↗</span></footer></div></button></div></template>
 </div>
</section></div></Teleport></template>
<style scoped>
.note-history-backdrop{position:fixed;inset:0;background:#1b302952;z-index:185;display:flex;justify-content:flex-end}.note-history{width:min(850px,94vw);height:100dvh;background:#fbfcf5;box-shadow:-12px 0 50px #142c2429;display:flex;flex-direction:column;color:#3f5949;outline:none}.note-history>header{padding:25px 30px;display:flex;align-items:start;justify-content:space-between;border-bottom:1px solid #dde3d2}.note-history header small{font-size:9px;letter-spacing:.14em;color:#96a284}.note-history h2{font-size:25px;margin:8px 0}.note-history header p{font-size:11px;margin:0;color:#89957c}.note-history-tools{padding:18px 30px;display:flex;gap:12px;align-items:center;border-bottom:1px solid #e2e7d8}.note-history-tools label{margin:0;flex:0 0 130px}.note-history-tools select,.note-history-tools input{font-size:12px;margin:0}.note-history-tools input{min-width:0;flex:1}.note-history-tools button{font-size:11px;white-space:nowrap}.note-history-body{overflow:auto;padding:24px 30px 40px;flex:1;min-height:0}.note-history-summary{font-size:11px;color:#859375;margin-bottom:18px}.note-history-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;align-items:start}.note-history-card{padding:0;display:flex;align-items:stretch;flex-direction:column;text-align:left;gap:0;background:#fffefa;border:1px solid #dbe2cf;border-radius:10px;overflow:hidden}.note-history-card:hover{border-color:#a3b592;background:#fffefa}.note-history-image{height:175px;background:#ecefdf;display:flex;align-items:center;justify-content:center;color:#9ca88b;font:20px 'SimSun',serif}.note-history-image img{width:100%;height:100%;object-fit:contain}.note-history-caption{padding:17px;width:100%}.note-category{font-size:10px;color:#7a916a}.note-history-caption p{font-size:13px;line-height:1.9;white-space:pre-wrap;overflow-wrap:anywhere;color:#4f634b;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden;margin:10px 0 14px}.note-history-caption small{font-size:10px;color:#929d85}.note-history-caption footer{display:flex;justify-content:space-between;border-top:1px solid #e7ebdf;padding-top:13px;margin:14px 0 0;font-size:10px;color:#839474}.note-history-empty{padding:70px 20px;text-align:center}.note-history-empty>span{display:block;font:48px 'SimSun',serif;color:#b0bda0;margin-bottom:25px}.note-history-empty h3{font-weight:400;font-size:17px}.note-history-empty p{font-size:12px;max-width:350px;margin:15px auto;line-height:2;color:#939f85}.note-history-back{font-size:11px;margin-bottom:20px}.note-detail{border:1px solid #dfe5d4;background:#fffefa;border-radius:10px;padding:20px}.note-detail a{display:block;color:#6b865a;font-size:11px;text-decoration:none;margin-bottom:22px}.note-detail img{display:block;max-width:100%;max-height:60dvh;object-fit:contain;margin:0 auto 12px;background:#edf0e4}.note-detail p{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:2;color:#42583e;margin:20px 0}.note-detail small{font-size:11px;line-height:1.9;color:#8c9a7d}.note-history-error p{color:#a46b54;font-size:12px}
@media(max-width:650px){.note-history-grid{grid-template-columns:1fr}.note-history>header,.note-history-tools,.note-history-body{padding-left:20px;padding-right:20px}.note-history-tools{flex-wrap:wrap}.note-history-tools input{order:3;flex-basis:100%}.note-history-tools button{margin-left:auto}}
</style>
